INSERT INTO faqs (question, answer, sort_order) VALUES
  ('How early should I book?', 'For weddings and large events, 3 to 6 months ahead is ideal. For smaller events, contact us and we''ll check availability.', 0),
  ('Do you work within a budget?', 'Yes. Tell us your budget and we''ll suggest what''s possible, then send an itemised quote.', 1),
  ('Can I hire only decor or rentals?', 'Yes. You can book full planning, decor only, rentals only or day-of coordination.', 2),
  ('Do you travel outside the city?', 'Yes. Travel and logistics costs are added to the quote.', 3),
  ('How do I secure my date?', 'Your date is secured once you accept the quote and pay the deposit.', 4);
